package com.telecom.tollfree.service;
import com.telecom.tollfree.domain.*; import com.telecom.tollfree.messaging.NumberEventPublisher; import com.telecom.tollfree.repository.*; import org.junit.jupiter.api.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class NumberServiceTest { TelecomNumberRepository numbers=mock(TelecomNumberRepository.class); AuditLogRepository audits=mock(AuditLogRepository.class); NumberEventPublisher events=mock(NumberEventPublisher.class); NumberService service=new NumberService(numbers,audits,events); @Test void rejectsInvalidTransition(){TelecomNumber n=new TelecomNumber("8001234567");when(numbers.lockByNumber(n.getNumber())).thenReturn(Optional.of(n));assertThrows(ConflictException.class,()->service.transition(n.getNumber(),NumberStatus.ACTIVE));} @Test void reservesAvailableNumberAndPublishes(){TelecomNumber n=new TelecomNumber("8001234567");Customer c=new Customer();when(numbers.lockByNumber(n.getNumber())).thenReturn(Optional.of(n));var result=service.reserve(n.getNumber(),c);assertEquals(NumberStatus.RESERVED,result.status());verify(events).publish(argThat(e->e.eventType().equals("NumberReserved")));} @Test void missingNumberIsNotFound(){when(numbers.lockByNumber("8001234567")).thenReturn(Optional.empty());assertThrows(NotFoundException.class,()->service.transition("8001234567",NumberStatus.RESERVED));}}
